function seoStripTags(html){
  return String(html||'').replace(/<script[\s\S]*?<\/script>/gi,'').replace(/<style[\s\S]*?<\/style>/gi,'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();
}
function seoGet(html, re){
  var m = String(html||'').match(re);
  return m ? (m[1]!==undefined ? m[1] : m[0]) : '';
}
function seoExtractMeta(html){
  var h = String(html||'');
  var meta = {};
  meta.title = seoGet(h, /<title[^>]*>([\s\S]*?)<\/title>/i);
  meta.description = seoGet(h, /<meta[^>]+name=["']description["'][^>]*content=["']([^"']*)["']/i) || seoGet(h, /<meta[^>]+content=["']([^"']*)["'][^>]*name=["']description["']/i);
  var mm, ogRe = /<meta[^>]+property=["']og:([a-z]+)["'][^>]*content=["']([^"']*)["']/gi;
  while((mm = ogRe.exec(h))) meta['og_'+mm[1]] = mm[2];
  var ogRe2 = /<meta[^>]+content=["']([^"']*)["'][^>]*property=["']og:([a-z]+)["']/gi;
  while((mm = ogRe2.exec(h))) if(!meta['og_'+mm[2]]) meta['og_'+mm[2]] = mm[1];
  var twRe = /<meta[^>]+name=["']twitter:([a-z]+)["'][^>]*content=["']([^"']*)["']/gi;
  while((mm = twRe.exec(h))) meta['tw_'+mm[1]] = mm[2];
  meta.canonical = seoGet(h, /<link[^>]+rel=["']canonical["'][^>]*href=["']([^"']*)["']/i) || seoGet(h, /<link[^>]+href=["']([^"']*)["'][^>]*rel=["']canonical["']/i);
  meta.viewport = seoGet(h, /<meta[^>]+name=["']viewport["'][^>]*content=["']([^"']*)["']/i);
  meta.jsonld = (h.match(/application\/ld\+json/gi)||[]).length;
  meta.h1 = (h.match(/<h1[\s\S]*?<\/h1>/gi)||[]).length;
  meta.h2 = (h.match(/<h2[\s\S]*?<\/h2>/gi)||[]).length;
  meta.lang = seoGet(h, /<html[^>]+lang=["']([^"']*)["']/i);
  return meta;
}
function seoLen(s){ return String(s||'').length; }
function seoScore(m){
  var checks = [];
  function add(name, pass, weight){ checks.push({name:name, pass:!!pass, weight:weight||0}); }
  add('标题存在', seoLen(m.title)>0, 15);
  add('标题长度 30-60', seoLen(m.title)>=30 && seoLen(m.title)<=60, 5);
  add('描述存在', seoLen(m.description)>0, 15);
  add('描述长度 70-160', seoLen(m.description)>=70 && seoLen(m.description)<=160, 5);
  add('og:title', seoLen(m.og_title)>0, 8);
  add('og:description', seoLen(m.og_description)>0, 6);
  add('og:image', seoLen(m.og_image)>0, 8);
  add('canonical', seoLen(m.canonical)>0, 6);
  add('viewport', seoLen(m.viewport)>0, 7);
  add('结构化数据', m.jsonld>0, 10);
  add('h1 恰好一个', m.h1===1, 8);
  add('lang 属性', seoLen(m.lang)>0, 7);
  var total=0, got=0;
  for(var i=0;i<checks.length;i++){ total+=checks[i].weight; if(checks[i].pass) got+=checks[i].weight; }
  return { score: got, max: total, checks: checks };
}
function seoKeywordDensity(text, topN){
  var clean = String(text||'').toLowerCase().replace(/[^a-z\u4e00-\u9fa5\s]/g,' ').split(/\s+/).filter(function(w){ return w.length>1; });
  var freq={}, i, total=clean.length;
  for(i=0;i<clean.length;i++) freq[clean[i]]=(freq[clean[i]]||0)+1;
  var arr=[];
  for(var k in freq) arr.push({word:k, count:freq[k], density: total? Math.round(freq[k]/total*1000)/10 : 0});
  arr.sort(function(a,b){ return b.count-a.count; });
  return arr.slice(0, topN||10);
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { seoStripTags:seoStripTags, seoExtractMeta:seoExtractMeta, seoScore:seoScore, seoKeywordDensity:seoKeywordDensity, seoLen:seoLen };
}
if (typeof window !== 'undefined') {
  window.SeoForgePure = { seoStripTags:seoStripTags, seoExtractMeta:seoExtractMeta, seoScore:seoScore, seoKeywordDensity:seoKeywordDensity, seoLen:seoLen };
}
